// Each Account → List<Trade> (but map WRAPS it!)
Stream<List<Trade>> nested = accounts.stream()
    .map(Account::getTrades);         // Stream<List<Trade>> — NESTED!
// Can't filter individual trades — they're trapped inside Lists!

// ═══ flatMap: one-to-many + flatten — UNWRAPS ═══
Stream<Trade> flat = accounts.stream()
    .flatMap(a -> a.getTrades().stream());  // Stream<Trade> — FLAT!
// Every trade is a top-level element — can filter, sort, count individually

// ═══ VISUAL: ═══
// Account A → [Trade1, Trade2, Trade3]
// Account B → [Trade4, Trade5]
// Account C → [Trade6]

// map(Account::getTrades):
// → Stream<List<Trade>>: [[T1,T2,T3], [T4,T5], [T6]]  — 3 elements (Lists)

// flatMap(a → a.getTrades().stream()):
// → Stream<Trade>: [T1, T2, T3, T4, T5, T6]  — 6 elements (Trades)
```

