Stream<BigDecimal> fees = trades.stream()
    .map(Trade::getOptionalFee)       // Stream<Optional<BigDecimal>> — nested Optionals!
    .flatMap(Optional::stream)         // Stream<BigDecimal> — flat! Empty optionals removed!
// Optional.stream(): present → Stream.of(value), empty → Stream.empty()
