package com.bank.dashboard.service;

import com.bank.dashboard.dto.DashboardResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;

@Service
@Slf4j
public class DashboardService {

    // Simulated data — Customer → Accounts → Trades
    record Trade(String id, String symbol, BigDecimal amount, Optional<BigDecimal> fee) {}
    record Account(String accountId, List<Trade> trades) {}

    private final List<Account> accounts = List.of(
        new Account("SAV2001", List.of(
            new Trade("T1", "RELIANCE", new BigDecimal("245050"), Optional.of(new BigDecimal("245"))),
            new Trade("T2", "TCS", new BigDecimal("176000"), Optional.empty()),
            new Trade("T3", "HDFC", new BigDecimal("330150"), Optional.of(new BigDecimal("330")))
        )),
        new Account("CUR3001", List.of(
            new Trade("T4", "INFY", new BigDecimal("222037"), Optional.of(new BigDecimal("222"))),
            new Trade("T5", "WIPRO", new BigDecimal("33664"), Optional.empty())
        )),
        new Account("FD4001", List.of(
            new Trade("T6", "RELIANCE", new BigDecimal("123750"), Optional.of(new BigDecimal("124")))
        ))
    );

    public DashboardResponse buildDashboard() {

        // ═══ MAP: Account → List<Trade> = Stream<List<Trade>> — NESTED! ═══
        List<List<Trade>> nested = accounts.stream()
            .map(Account::trades)           // Stream<List<Trade>>
            .toList();
        // nested = [[T1,T2,T3], [T4,T5], [T6]] — 3 elements (Lists, not Trades!)
        log.info("[map] Nested lists: {} elements (Lists, not Trades)", nested.size());

        // ═══ FLATMAP: Account → Stream<Trade> = Stream<Trade> — FLAT! ═══
        List<Trade> flat = accounts.stream()
            .flatMap(a -> a.trades().stream())  // Stream<Trade> — all trades flat
            .toList();
        // flat = [T1, T2, T3, T4, T5, T6] — 6 elements (individual Trades!)
        log.info("[flatMap] Flat trades: {} elements (individual Trades)", flat.size());

        // Now we can filter, sort, aggregate individual trades:
        BigDecimal totalValue = accounts.stream()
            .flatMap(a -> a.trades().stream())
            .map(Trade::amount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        List<String> allSymbols = accounts.stream()
            .flatMap(a -> a.trades().stream())
            .map(Trade::symbol)
            .distinct().sorted()
            .toList();

        // ═══ FLATMAP with Optional — extract fees (skip empty) ═══
        BigDecimal totalFees = accounts.stream()
            .flatMap(a -> a.trades().stream())         // flatten accounts → trades
            .map(Trade::fee)                           // Stream<Optional<BigDecimal>>
            .flatMap(Optional::stream)                 // flatten: present → value, empty → gone
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info("[flatMap+Optional] Total fees: Rs.{} (empty fees skipped)", totalFees);

        return new DashboardResponse("CUST-001", accounts.size(), flat.size(),
            totalValue, allSymbols,
            "map → Stream<List<Trade>> (" + nested.size() + " Lists)",
            "flatMap → Stream<Trade> (" + flat.size() + " individual Trades)"
        );
    }
}
