package com.bank.dashboard.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class MapVsFlatMapTest {

    @Test
    void mapWrapsResultIntoNestedStructure() {
        List<List<String>> nested = List.of(
            List.of("RELIANCE", "TCS"),
            List.of("HDFC"),
            List.of("INFY", "WIPRO")
        ).stream()
            .map(list -> list)             // map: each List stays as-is
            .toList();                      // Stream<List<String>>

        assertThat(nested).hasSize(3);     // 3 Lists, not 5 Strings!
    }

    @Test
    void flatMapFlattensToSingleStream() {
        List<String> flat = List.of(
            List.of("RELIANCE", "TCS"),
            List.of("HDFC"),
            List.of("INFY", "WIPRO")
        ).stream()
            .flatMap(Collection::stream)   // flatMap: flatten!
            .toList();                      // Stream<String>

        assertThat(flat).hasSize(5);       // 5 individual Strings!
        assertThat(flat).containsExactly("RELIANCE", "TCS", "HDFC", "INFY", "WIPRO");
    }

    @Test
    void flatMapWithStringSplitting() {
        List<String> words = List.of("RELIANCE,TCS", "HDFC,INFY,WIPRO").stream()
            .map(line -> line.split(","))    // Stream<String[]>
            .flatMap(Arrays::stream)         // Stream<String>
            .toList();

        assertThat(words).containsExactly("RELIANCE", "TCS", "HDFC", "INFY", "WIPRO");
    }

    @Test
    void flatMapWithOptionalStream() {
        List<Optional<String>> opts = List.of(
            Optional.of("RELIANCE"), Optional.empty(), Optional.of("TCS"), Optional.empty());

        List<String> present = opts.stream()
            .flatMap(Optional::stream)     // present → Stream.of(v), empty → Stream.empty()
            .toList();

        assertThat(present).containsExactly("RELIANCE", "TCS");  // empties removed!
    }

    @Test
    void flatMapCanProduceZeroElements() {
        // flatMap: each element can produce 0, 1, or many
        List<String> result = List.of(1, 2, 3).stream()
            .flatMap(n -> n == 2 ? Stream.empty() : Stream.of("V" + n))  // 2 → nothing
            .toList();

        assertThat(result).containsExactly("V1", "V3");  // 2 produced ZERO elements
    }
}
